// supabase/migrations/20261105150000_int_lender_contacts_research.sql on PGlite: the contact research
// (research_notes/Wholesale lender directory/research3_contacts, generated by gen_contacts_sql.py)
// fills only blank fields, never overwrites what a broker entered, adds the routed lenders the
// directory seed left off the panel, keeps contact values out of audit_log and is idempotent.
import type { PGlite } from "@electric-sql/pglite";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { applyMigrations, createStubbedDb, custodyViolations, lintMigrationNames, lintWorkstreamSlots, listMigrations } from "../../scripts/test-migrations.ts";

const MIGRATION = "20261105150000_int_lender_contacts_research.sql";
const MARKER = "migration:20261105150000_int_lender_contacts_research";
const RESEARCH = join(process.cwd(), "research_notes/Wholesale lender directory/research3_contacts/contacts.json");
const ROUTED = ["Cambridge Realty Capital", "Greystone", "Lument", "VIUM Capital", "TMC Financing", "Harvest Small Business Finance", "Liberty SBF", "Ready Capital", "Roc Capital (Roc360)", "Fidelis Private Fund"];

type Research = { id: string; name: string; status: string | null; main_phone: string | null; contacts: { full_name: string }[] | null; notes: string | null };
const researched = (JSON.parse(readFileSync(RESEARCH, "utf8")) as Research[]).filter((r) => r.status && !(r.notes ?? "").includes("NOT RESEARCHED"));

const files = listMigrations();
const index = files.findIndex((f) => f.name === MIGRATION);
const before = files.slice(0, index);
const target = files[index]!;

let db: PGlite;
const rows = async <T = Record<string, unknown>>(sql: string, params: unknown[] = []) => (await db.query<T>(sql, params)).rows;
const one = async <T = Record<string, unknown>>(sql: string, params: unknown[] = []) => (await rows<T>(sql, params))[0]!;
const n = async (sql: string, params: unknown[] = []) => Number((await one<{ n: number }>(sql, params)).n);

// A seeded lender the research found a phone and a named contact for, to edit as a broker would before the migration runs.
const withPhoneAndContact = researched.find((r) => /^[0-9a-f-]{36}$/.test(r.id) && r.main_phone && (r.contacts ?? []).length > 0)!;
const withPhone = researched.find((r) => /^[0-9a-f-]{36}$/.test(r.id) && r.main_phone && r.id !== withPhoneAndContact.id)!;

let snapshot: { phones: number; contacts: number };

beforeAll(async () => {
  db = await createStubbedDb();
  await applyMigrations(db, before);
  snapshot = {
    phones: await n(`select count(*)::int as n from public.lender_panel where main_phone is not null`),
    contacts: await n(`select count(*)::int as n from public.lender_contacts`),
  };
  // Broker edits made on the live site before this migration: a phone, a website and a primary contact.
  await db.query(`update public.lender_panel set main_phone = '+13105550142', website_url = 'https://broker-entered.example', contact_info_version = contact_info_version + 1, updated_by = 'broker:ana' where id = $1`, [withPhoneAndContact.id]);
  await db.query(`delete from public.lender_contacts where lender_id = $1`, [withPhoneAndContact.id]);
  await db.query(`insert into public.lender_contacts (lender_id, full_name, is_primary, created_by) values ($1, 'Pat Broker-Entered', true, 'broker:ana')`, [withPhoneAndContact.id]);
  // A staff-added row for a routed lender under a longer name.
  await db.query(`insert into public.lender_panel (name, category, programs, updated_by) values ('Greystone Housing (staff added)', 'UNKNOWN', '{HUD_232}', 'broker:ana')`);
  await applyMigrations(db, [target]);
}, 180_000);

afterAll(async () => {
  await db?.close();
});

describe("lender contact research migration", () => {
  it("passes the migration lints and the no-custody guard", async () => {
    expect(index).toBeGreaterThan(0);
    expect(lintMigrationNames(files)).toEqual([]);
    expect(lintWorkstreamSlots(files)).toEqual([]);
    expect(await custodyViolations(db)).toEqual([]);
  });

  it("fills phones and adds named contacts for the researched lenders", async () => {
    expect(researched.length).toBeGreaterThan(50);
    expect(await n(`select count(*)::int as n from public.lender_panel where main_phone is not null`)).toBeGreaterThan(snapshot.phones + 30);
    expect(await n(`select count(*)::int as n from public.lender_contacts`)).toBeGreaterThan(snapshot.contacts + 30);
    const p = await one<{ main_phone: string }>(`select main_phone from public.lender_panel where id = $1`, [withPhone.id]);
    expect(p.main_phone).toMatch(/^\+1[2-9]\d{9}$/);
  });

  it("never overwrites what a broker entered, and moves the contact-info version on", async () => {
    const l = await one<{ main_phone: string; website_url: string; updated_by: string }>(`select main_phone, website_url, updated_by from public.lender_panel where id = $1`, [withPhoneAndContact.id]);
    expect(l.main_phone).toBe("+13105550142");
    expect(l.website_url).toBe("https://broker-entered.example");
    const primaries = await rows<{ full_name: string }>(`select full_name from public.lender_contacts where lender_id = $1 and is_primary`, [withPhoneAndContact.id]);
    expect(primaries).toEqual([{ full_name: "Pat Broker-Entered" }]);
    // The research contacts were still added, as non-primary.
    expect(await n(`select count(*)::int as n from public.lender_contacts where lender_id = $1 and created_by = $2 and not is_primary`, [withPhoneAndContact.id, MARKER])).toBeGreaterThan(0);
  });

  it("keeps the seed's updated_by on seeded rows and leaves every new contact unverified", async () => {
    expect(await n(`select count(*)::int as n from public.lender_panel where id = $1 and updated_by like 'seed:lender-directory%'`, [withPhone.id])).toBe(1);
    expect(await n(`select count(*)::int as n from public.lender_contacts where created_by = $1 and (verified_at is not null or source not in ('lender_website', 'directory_import'))`, [MARKER])).toBe(0);
    expect(await n(`select count(*)::int as n from (select lender_id from public.lender_contacts where is_primary group by lender_id having count(*) > 1) x`)).toBe(0);
  });

  it("adds the routed lenders inactive and unverified, except one already on the panel", async () => {
    const added = await rows<{ name: string; active: boolean; category: string; verified_at: string | null; loan_types: string[] }>(
      `select name, active, category, verified_at, loan_types from public.lender_panel where name = any($1::text[]) and updated_by = $2 order by name`,
      [ROUTED, MARKER],
    );
    expect(added.map((r) => r.name).sort()).toEqual(ROUTED.filter((r) => r !== "Greystone").sort());
    expect(added.every((r) => !r.active && r.category === "UNKNOWN" && r.verified_at === null)).toBe(true);
    expect(added.filter((r) => r.loan_types.length > 0).length).toBeGreaterThanOrEqual(7);
    expect(await n(`select count(*)::int as n from public.lender_panel where lower(name) like 'greystone%'`)).toBe(1);
  });

  it("keeps contact values out of audit_log", async () => {
    const names = (await rows<{ full_name: string }>(`select full_name from public.lender_contacts where created_by = $1`, [MARKER])).map((r) => r.full_name);
    expect(names.length).toBeGreaterThan(0);
    const blob = (await rows<{ b: string }>(`select coalesce(old_row::text, '') || coalesce(new_row::text, '') as b from public.audit_log where table_name = 'lender_contacts'`)).map((r) => r.b).join("\n");
    for (const name of names) expect(blob).not.toContain(name);
  });

  it("changes nothing when applied again", async () => {
    const count = async () => [
      await n(`select count(*)::int as n from public.lender_contacts`),
      await n(`select count(*)::int as n from public.lender_panel`),
      await n(`select coalesce(sum(contact_info_version), 0)::int as n from public.lender_panel`),
      await n(`select count(*)::int as n from public.audit_log`),
    ];
    const first = await count();
    await applyMigrations(db, [target]);
    expect(await count()).toEqual(first);
  });
});
